def two_num_translate(n: int, num2word: Dict[int, str] = num2word) -> str:
    if n in num2word:
        translate = num2word[n]
    else:
        first_num = n // 10 * 10
        second_num = n % 10
        translate = f'{num2word[first_num]}-{num2word[second_num]}'
    return translate
